<script setup>
import { Head, Link, useForm, usePage, router } from '@inertiajs/vue3';
import DateTimePicker from '../../../Components/Shared/DateTimePicker.vue';
import AppLayout from '../../../Layouts/AppLayout.vue';
defineOptions({ layout: AppLayout });
const props = defineProps({ deliveryEnabled: Boolean, schedule: Object, products: Array, submitUrl: String, skipUrl: String, backUrl: String });
const page = usePage();
const names = ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
const form = useForm({ enabled: props.schedule?.enabled || false, days: names.map((name, index) => { const day = props.schedule?.days?.[index]; return { enabled: day?.enabled ?? true, opens: day?.opens || '08:00', closes: day?.closes || '17:00', delivery_starts: day?.delivery_starts || '17:30', delivery_ends: day?.delivery_ends || '19:00', product_ids: [...(day?.product_ids ?? props.schedule?.product_ids ?? [])] }; }) });
</script>
<template>
<Head title="Weekly schedule"/><Link :href="backUrl" class="text-sm text-stone-500">← Open orders</Link>
<form @submit.prevent="form.put(submitUrl,{preserveScroll:true})" class="mx-auto mt-6 max-w-3xl space-y-6"><div><h1 class="text-3xl font-semibold">Weekly schedule</h1><p class="mt-3 text-sm leading-6 text-stone-500">Choose opening hours and a menu for each day. Sessions open automatically. Times are in WIB.</p></div>
<p v-if="page.props.status" role="status" class="rounded-xl bg-green-50 p-4 text-sm text-green-800">{{ page.props.status }}</p><p v-if="schedule?.last_error" class="rounded-xl bg-amber-50 p-4 text-sm text-amber-800">{{ schedule.last_error }}</p>
<section class="rounded-2xl border border-stone-200 bg-white p-5"><label class="flex items-center gap-3 font-medium"><input v-model="form.enabled" type="checkbox">Enable automatic opening</label><div v-for="(day,index) in form.days" :key="index" class="mt-4 grid grid-cols-2 items-center gap-3 border-t border-stone-100 pt-4 sm:grid-cols-[1fr_1fr_1fr]"><label class="col-span-2 flex items-center gap-3 text-sm sm:col-span-1"><input v-model="day.enabled" type="checkbox">{{ names[index] }}<span v-if="!day.enabled" class="text-stone-400">Closed</span></label><DateTimePicker v-model="day.opens" :name="`weekly-${index}-opens`" label="Opens" time-only :disabled="!day.enabled"/><DateTimePicker v-model="day.closes" :name="`weekly-${index}-closes`" label="Closes" time-only :disabled="!day.enabled"/><div v-if="day.enabled && deliveryEnabled" class="col-span-2 grid gap-3 sm:col-span-3 sm:grid-cols-2"><DateTimePicker v-model="day.delivery_starts" :name="`weekly-${index}-delivery-start`" label="Delivery starts" time-only/><DateTimePicker v-model="day.delivery_ends" :name="`weekly-${index}-delivery-end`" label="Estimated delivery ends" time-only/></div><details v-if="day.enabled" class="col-span-2 rounded-xl border border-stone-200 p-3 sm:col-span-3"><summary class="cursor-pointer text-sm font-medium">Menu · {{ day.product_ids.length }} selected</summary><div class="mt-3 grid gap-2 sm:grid-cols-2"><label v-for="product in products" :key="product.id" class="flex items-center gap-3 rounded-lg border border-stone-100 p-3 text-sm"><input v-model="day.product_ids" type="checkbox" :value="product.id">{{ product.name }}</label></div><p v-if="!products.length" class="mt-3 text-sm text-stone-500">Add products to your catalog first.</p></details></div></section>

<p class="text-sm leading-6 text-stone-500">A new session waits until previous orders are completed. Stop orders still works for today's session.</p><p v-for="(message,key) in form.errors" :key="key" role="alert" class="text-sm text-red-700">{{ message }}</p><div class="flex flex-wrap gap-3"><button :disabled="form.processing" class="rounded-full bg-[#504941] px-5 py-3 text-sm text-white disabled:opacity-40">{{ form.processing ? 'Saving…' : 'Save schedule' }}</button><button v-if="schedule" type="button" class="rounded-full border border-stone-300 px-5 py-3 text-sm" @click="router.post(skipUrl,{}, {preserveScroll:true})">Skip automatic opening today</button></div></form>
</template>
